Scripts.OnMouseDown:
if ( self:IsEnabled() == 1 ) then
self.normalTexture:SetPoint("CENTER", 1, -1);
self.highlightTexture:SetPoint("CENTER", 1, -1);
end

Scripts.OnEnter:
                self:GetParent():LockHighlight();
                local deactivate = self:GetParent().DeactivateButton;
				if deactivate and not CharacterSelect.viewingInactiveList then
					local guid = deactivate.guid or deactivate.deactivateGuid
					if guid and guid ~= 0 then
						deactivate:Show();
					end
				end

Scripts.OnLeave:
local parent = self:GetParent();
if parent and not parent.selected and not parent:IsMouseOver() and not (parent.DeactivateButton and parent.DeactivateButton:IsMouseOver()) then
    parent:UnlockHighlight();
end

Scripts.OnClick:
PlaySound("igMainMenuOptionCheckBoxOn");
local index = self:GetParent().index;
MoveCharacter(index, index - 1);
self:Hide()
self:GetParent().downButton:Hide()
self:GetParent().moved = true

PlaySound("igMainMenuOptionCheckBoxOn");
local index = self:GetParent().index;
MoveCharacter(index, index + 1);
self:Hide()
self:GetParent().upButton:Hide()
self:GetParent().moved = true

Scripts.OnEnter:
local parent = self:GetParent();
if parent and not parent.selected then
    parent:LockHighlight();
end
GlueTooltip:SetOwner(self, "ANCHOR_TOPLEFT");
GlueTooltip:SetText(CHARACTER_DEACTIVATE or "");
if CHARACTER_DEACTIVATE_TOOLTIP then
    GlueTooltip:AddLine(CHARACTER_DEACTIVATE_TOOLTIP, 1, 1, 1, true);
end
GlueTooltip:Show();

Scripts.OnLeave:
local parent = self:GetParent();
if parent and not parent.selected and not parent:IsMouseOver() then
    parent:UnlockHighlight();
end
GlueTooltip:Hide();

Scripts.OnEnter:
local isInactive = CharacterSelect.viewingInactiveList;
if isInactive then
    GlueTooltip:SetOwner(self, "ANCHOR_TOPLEFT");
    GlueTooltip:SetText(SHOW_ACTIVE_CHARACTERS or "");
    if SHOW_ACTIVE_CHARACTERS_TOOLTIP then
        GlueTooltip:AddLine(SHOW_ACTIVE_CHARACTERS_TOOLTIP, 1, 1, 1, true);
    end
    GlueTooltip:Show();
else
    GlueTooltip:SetOwner(self, "ANCHOR_TOPLEFT");
    GlueTooltip:SetText(SHOW_INACTIVE_CHARACTERS or "");
    if SHOW_INACTIVE_CHARACTERS_TOOLTIP then
        GlueTooltip:AddLine(SHOW_INACTIVE_CHARACTERS_TOOLTIP, 1, 1, 1, true);
    end
    GlueTooltip:Show();
end

Scripts.OnTextChanged:
if ( strupper(self:GetText()) == strupper(DELETE_CONFIRM_STRING) ) then
CharacterDeleteButton1:Enable();
else
CharacterDeleteButton1:Disable();
end
